//! Per-model command support from Onkyo's protocol spreadsheet
//! (assets/models.json, generated by tools/gen_model_table.py).

use std::collections::{BTreeMap, HashMap};
use std::sync::OnceLock;

use serde::Deserialize;

/// Command group -> supported values ("00", "UP", "QSTN", "0..100", ...).
pub type ModelTable = BTreeMap<String, Vec<String>>;

#[derive(Deserialize)]
struct File {
    source: String,
    tables: Vec<ModelTable>,
    models: HashMap<String, usize>,
}

fn file() -> &'static File {
    static FILE: OnceLock<File> = OnceLock::new();
    FILE.get_or_init(|| {
        serde_json::from_slice(include_bytes!("../assets/models.json"))
            .expect("embedded models.json is valid")
    })
}

/// Name of the spreadsheet the table was generated from.
pub fn source() -> &'static str {
    &file().source
}

/// The command table for a model name as the receiver reports it (e.g.
/// "DTR-50.7"), or None if the spreadsheet doesn't list it.
pub fn lookup(model: &str) -> Option<&'static ModelTable> {
    let f = file();
    let model = model.trim();
    if model.is_empty() {
        return None;
    }
    f.models
        .get(model)
        .or_else(|| {
            // Receivers sometimes report a regional suffix ("TX-NR646E").
            f.models
                .iter()
                .filter(|(name, _)| model.starts_with(name.as_str()))
                .max_by_key(|(name, _)| name.len())
                .map(|(_, i)| i)
        })
        .map(|&i| &f.tables[i])
}

/// Whether `value` is listed for `group`, also matching numeric ranges
/// ("0..100" covers "3A").
pub fn table_supports(table: &ModelTable, group: &str, value: &str) -> bool {
    let Some(values) = table.get(group) else {
        return false;
    };
    values.iter().any(|v| {
        if v.eq_ignore_ascii_case(value) {
            return true;
        }
        let Some((lo, hi)) = v.split_once("..") else {
            return false;
        };
        match (
            lo.parse::<i64>(),
            hi.parse::<i64>(),
            i64::from_str_radix(value, 16),
        ) {
            (Ok(lo), Ok(hi), Ok(n)) => (lo..=hi).contains(&n),
            _ => false,
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn dtr_50_7() {
        let t = lookup("DTR-50.7").expect("DTR-50.7 is in the spreadsheet");
        assert!(table_supports(t, "DIM", "02"));
        assert!(!table_supports(t, "DIM", "03"));
        assert!(table_supports(t, "HAO", "02"));
        assert!(table_supports(t, "MVL", "3A"));
        assert!(!table_supports(t, "MVL", "C8"));
        assert!(t.contains_key("ZVL"));
        assert!(!t.contains_key("RES"));
        assert!(lookup("NOT-A-MODEL").is_none());
    }
}
